style.css:
@-moz-document domain("tumblr.com") {
body {
    background: url("https://i.pinimg.com/originals/64/3a/5b/643a5b6a2366117d63f548bb7260d54e.jpg") no-repeat center center fixed;
    background-size: cover;
    color: #e6c6ff !important;
    font-family: "Gothic A1", "Georgia", serif !important;
  }

  /* Transparent dark overlay for readability */
  #tumblr_lightbox, .l-content, .NJFfW, .CzkRI, .YFxxa {
    background-color: rgba(0, 0, 0, 0.7) !important;
    color: #fce6ff !important;
    border-radius: 10px;
  }

  /* Links */
  a {
    color: #ff66cc !important;
  }

  a:visited {
    color: #b300b3 !important;
  }

  /* Buttons */
  button, .Z8hZb {
    background-color: #2a002a !important;
    color: #ffffff !important;
    border: 1px solid #a000a0 !important;
    font-family: "Gothic A1", "Georgia", serif !important;
    border-radius: 6px;
  }

  /* Dashboard header */
  .Va, .Hv, .Jb {
    background-color: rgba(0, 0, 0, 0.8) !important;
    color: #ffccff !important;
  }

  /* Posts background */
  article, .post_body {
    background-color: rgba(30, 0, 30, 0.75) !important;
    color: #f3d1ff !important;
    border: 1px solid #a64ca6 !important;
    padding: 10px;
    border-radius: 8px;
  }

  /* Hide explore popups or annoying sections if you want */
  .NyeI_, .EXg_k {
    display: none !important;
  }
}
